// The execution-layer system contracts mainnet runs, as `genesisAccounts` for
// an L1 artifacts spec (see el-genesis.ts / state-root.ts).
//
// EIP-4788 / 2935 / 7002 / 7251 (bytecodes from alloy-eips 2.0.5, the constants
// reth itself uses): the EL makes their pre/post-block system calls EVERY
// block. With no code at those addresses the calls touch non-existent accounts
// and the block's state diff takes a shape mainnet never produces - which is
// exactly the kind of difference that makes a builder or a prover behave
// differently here than in production.
//
// A recipe spreads these into its own `genesisAccounts` and adds whatever else
// it needs:
//
//   genesisAccounts: { ...MAINNET_SYSTEM_CONTRACTS, [myAddr]: myPredeploy }
import type { GenesisAlloc } from "./state-root.ts";

const CODE = {
  eip4788: "0x3373fffffffffffffffffffffffffffffffffffffffe14604d57602036146024575f5ffd5b5f35801560495762001fff810690815414603c575f5ffd5b62001fff01545f5260205ff35b5f5ffd5b62001fff42064281555f359062001fff015500",
  eip2935: "0x3373fffffffffffffffffffffffffffffffffffffffe14604657602036036042575f35600143038111604257611fff81430311604257611fff9006545f5260205ff35b5f5ffd5b5f35611fff60014303065500",
  eip7002: "",
  eip7251: "",
};

// nonce 1 and no balance: what a deployed contract looks like on mainnet.
export const predeploy = (code: string) => ({ nonce: "0x1", balance: "0x0", code });

export const SYSTEM_CONTRACT_ADDRESSES = {
  eip4788: "0x000F3df6D732807Ef1319fB7B8bB8522d0Beac02", // beacon block roots
  eip2935: "0x0000F90827F1C53a10cb7A02335B175320002935", // historical block hashes
  eip7002: "0x00000961Ef480Eb55e80D19ad83579A64c007002", // withdrawal requests
  eip7251: "0x0000BBdDc7CE488642fb579F8B00f3a590007251", // consolidation requests
} as const;

export const MAINNET_SYSTEM_CONTRACTS: GenesisAlloc = {
  [SYSTEM_CONTRACT_ADDRESSES.eip4788]: predeploy(CODE.eip4788),
  [SYSTEM_CONTRACT_ADDRESSES.eip2935]: predeploy(CODE.eip2935),
  [SYSTEM_CONTRACT_ADDRESSES.eip7002]: predeploy(CODE.eip7002),
  [SYSTEM_CONTRACT_ADDRESSES.eip7251]: predeploy(CODE.eip7251),
};
